\begin{corollary}
\label{cor:8-38}




\dcref{ch8:8.38}
Every left-invariant rough vector field on a Lie group is smooth.
\end{corollary}

\begin{proof}

\sketch If $v=X_e$, left invariance gives $X=v^L$, which is smooth by the
theorem.
\end{proof}

